84		apply := func(policy, account, sess, dev, rid string, fee int64) RequestView {
85			in := RequestInput{
86				PolicyID: policy, RequestID: rid, AccountID: account, SessionID: sess,
87				DeviceID: dev, Operation: "charge", Payee: "shop", EstimatedFee: fee,
88			}
89			v, err := w.Apply(in)
90			if err != nil {
91				t.Fatalf("apply %s/%s: %v", account, rid, err)
92			}
93			return v
94		}
95	
96		// 直接预留（p-app，费用 5 不超门槛）。
97		apply("p-app", "u1", "s1", "dev1", "direct", 5)
98		// 已结算（实际 3）。
99		apply("p-app", "u1", "s1", "dev1", "settled", 5)
100		if _, err := w.Settle("u1", "settled", 3); err != nil {
101			t.Fatal(err)
102		}
103		// 已预留后取消。
104		apply("p-app", "u1", "s1", "dev1", "cancel-reserved", 5)
105		if _, err := w.Cancel("u1", "cancel-reserved"); err != nil {
106			t.Fatal(err)
107		}
108		// 待审批（恢复时才到期）。
109		apply("p-app", "u1", "s1", "dev1", "pending-due", 20)
110		// 批准后预留。
111		apply("p-app", "u2", "s2", "dev2", "approved", 20)
112		if _, err := w.Approve("u2", "approved", "sa", "deva"); err != nil {
113			t.Fatal(err)
114		}
115		// 审批拒绝。
116		apply("p-app", "u2", "s2", "dev2", "rejected", 20)
117		if _, err := w.Reject("u2", "rejected", "sa", "deva", "no way"); err != nil {
118			t.Fatal(err)
119		}
