121		apply("p-app", "u2", "s2", "dev2", "cancel-pending", 20)
122		if _, err := w.Cancel("u2", "cancel-pending"); err != nil {
123			t.Fatal(err)
124		}
125		// 待审批等待过期（终态）：临时拨快时钟触发后拨回。
126		apply("p-app", "u2", "s2", "dev2", "pending-expired", 20)
127		c.t = t0.Add(6 * time.Minute)
128		if r, err := w.Request("u2", "pending-expired"); err != nil || r.State != RequestExpired {
129			t.Fatalf("pending-expired state = %v err = %v", r.State, err)
130		}
131		c.t = t0
132		// 预留超时（终态，释放时刻必须是原截止时刻 t0+1m）：拨快触发后拨回。
133		apply("p-to", "u1", "s1", "dev1", "resv-expired", 5)
134		c.t = t0.Add(2 * time.Minute)
135		if r, err := w.Request("u1", "resv-expired"); err != nil || r.State != RequestReservationExpired {
136			t.Fatalf("resv-expired state = %v err = %v", r.State, err)
137		}
138		c.t = t0
139		// 恢复时才到期的预留（截止 t0+1m，导出时仍存活）。
140		apply("p-to", "u1", "s1", "dev1", "resv-due", 5)
141		// 关闭预留超时：很久以后仍等待结算或取消。
142		apply("p-notime", "u1", "s1", "dev1", "no-timeout", 5)
143		// 同号不同使用账户：分别识别。
144		apply("p-notime", "u1", "s1", "dev1", "same-id", 5)
145		apply("p-notime", "u2", "s2", "dev2", "same-id", 5)
146	
147		// 未被受理申请的拒绝记录：空字段、未知账户、未知会话各一条。
148		if _, err := w.Apply(RequestInput{EstimatedFee: -1}); !errors.Is(err, ErrInvalidAmount) {
149			t.Fatalf("empty/invalid apply err = %v", err)
150		}
151		if _, err := w.Apply(RequestInput{
152			PolicyID: "p-app", RequestID: "ghost-rid", AccountID: "ghost",
153			SessionID: "s1", DeviceID: "dev1", Operation: "charge", Payee: "shop", EstimatedFee: 5,
154		}); !errors.Is(err, ErrAccountNotFound) {
155			t.Fatalf("ghost account apply err = %v", err)
156		}
157		if _, err := w.Apply(RequestInput{
158			PolicyID: "p-app", RequestID: "no-session", AccountID: "u1",
159			SessionID: "missing", DeviceID: "dev1", Operation: "charge", Payee: "shop", EstimatedFee: 5,
160		}); !errors.Is(err, ErrSessionNotFound) {
161			t.Fatalf("missing session apply err = %v", err)
162		}
163	
164		return w, c
165	}
