1401				restoreAt:  t0,
1402				wantPolicy: "p-shared",
1403			},
1404			{
1405				name: "reserved already due at restore is still counted",
1406				policies: []quotaPolicySpec{{
1407					id: "p-due", per: 30, total: 50, reserveDur: time.Minute,
1408					reqs: []quotaReqSpec{
1409						{id: "settled", account: "u1", estFee: 30, actualFee: 30, state: RequestSettled},
1410						{id: "reserved-due", account: "u1", estFee: 30, state: RequestReserved, due: true},
1411					},
1412				}},
1413				// 恢复时该预留已过截止时刻，按正常规则将全额退回，但仍须先拒绝。
1414				restoreAt:  t0,
1415				wantPolicy: "p-due",
1416			},
1417			{
1418				name: "second policy over limit is named",
1419				policies: []quotaPolicySpec{
1420					{
1421						id: "p1", per: 100, total: 50,
1422						reqs: []quotaReqSpec{
1423							{id: "s1", account: "u1", estFee: 30, actualFee: 20, state: RequestSettled},
1424							{id: "r1", account: "u1", estFee: 30, state: RequestReserved},
1425						},
1426					},
1427					{
1428						id: "p2", per: 100, total: 50,
1429						reqs: []quotaReqSpec{
1430							{id: "s2", account: "u1", estFee: 30, actualFee: 21, state: RequestSettled},
1431							{id: "r2", account: "u1", estFee: 30, state: RequestReserved},
1432						},
1433					},
1434				},
1435				restoreAt:  t0,
1436				wantPolicy: "p2",
1437			},
1438		}
1439		for _, tc := range cases {
1440			t.Run(tc.name, func(t *testing.T) {
1441				data := buildCumulativeQuotaBackup(t, t0, tc.policies)
1442				w2, err := restoreAt(data, tc.restoreAt)
1443				if err == nil {
1444					if w2 != nil {
1445						t.Fatalf("over-quota backup restored a wallet")
1446					}
1447					t.Fatalf("over-quota backup restored without error")
1448				}
1449				if !errors.Is(err, ErrBackupInvalid) {
1450					t.Fatalf("err = %v, want ErrBackupInvalid", err)
1451				}
1452				msg := err.Error()
1453				if !strings.Contains(msg, tc.wantPolicy) {
1454					t.Fatalf("error %q must name policy %q", msg, tc.wantPolicy)
1455				}
1456				if !strings.Contains(msg, "cumulative total limit") {
1457					t.Fatalf("error %q must explain the cumulative total limit", msg)
1458				}
1459			})
1460		}
1461	}
1462	
1463	// TestRestoreRejectsPolicyCumulativeQuotaOverflow 验证预留与已花费各自都能
1464	// 由 int64 表示、合计却越过 int64 上限时必须拒绝，不能因金额越界误判为
1465	// 额度充足。
1466	func TestRestoreRejectsPolicyCumulativeQuotaOverflow(t *testing.T) {
1467		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
1468		data := buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1469			id: "p-big", per: math.MaxInt64, total: math.MaxInt64,
1470			reqs: []quotaReqSpec{
1471				{id: "settled", account: "u1", estFee: math.MaxInt64, actualFee: math.MaxInt64, state: RequestSettled},
1472				{id: "reserved", account: "u1", estFee: 1, state: RequestReserved},
1473			},
1474		}})
1475		w2, err := restoreAt(data, t0)
1476		if err == nil {
1477			if w2 != nil {
1478				t.Fatalf("overflowing-quota backup restored a wallet")
1479			}
1480			t.Fatalf("overflowing-quota backup restored without error")
1481		}
1482		if !errors.Is(err, ErrBackupInvalid) {
1483			t.Fatalf("err = %v, want ErrBackupInvalid", err)
1484		}
1485		msg := err.Error()
1486		if !strings.Contains(msg, "p-big") || !strings.Contains(msg, "cumulative total limit") {
1487			t.Fatalf("error %q must name policy and cumulative limit", msg)
1488		}
1489	}
1490	
1491	// TestRestoreAcceptsCumulativeQuotaAtBoundary 验证合计恰好等于累计上限合法，
1492	// 包括上限恰为 int64 最大值的情况；不缩小现有金额范围。
1493	func TestRestoreAcceptsCumulativeQuotaAtBoundary(t *testing.T) {
1494		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
1495	
1496		// 上限 50：结算实际 20（预估 30，差额已退回）+ 现存预留 30 = 50。
1497		data := buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1498			id: "p-eq", per: 30, total: 50,
1499			reqs: []quotaReqSpec{
1500				{id: "settled", account: "u1", estFee: 30, actualFee: 20, state: RequestSettled},
1501				{id: "reserved", account: "u1", estFee: 30, state: RequestReserved},
1502			},
1503		}})
1504		if _, err := restoreAt(data, t0); err != nil {
1505			t.Fatalf("used == total restore: %v", err)
1506		}
1507	
1508		// 上限 MaxInt64：已花费 MaxInt64-1 + 预留 1 = MaxInt64。
1509		data = buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1510			id: "p-max", per: math.MaxInt64, total: math.MaxInt64,
1511			reqs: []quotaReqSpec{
1512				{id: "settled", account: "u1", estFee: math.MaxInt64, actualFee: math.MaxInt64 - 1, state: RequestSettled},
1513				{id: "reserved", account: "u1", estFee: 1, state: RequestReserved},
1514			},
1515		}})
1516		if _, err := restoreAt(data, t0); err != nil {
1517			t.Fatalf("used == MaxInt64 restore: %v", err)
1518		}
1519	
1520		// 上限 MaxInt64：单笔已结算实际费用 MaxInt64，占满额度。
1521		data = buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1522			id: "p-spent-max", per: math.MaxInt64, total: math.MaxInt64,
1523			reqs: []quotaReqSpec{
1524				{id: "settled", account: "u1", estFee: math.MaxInt64, actualFee: math.MaxInt64, state: RequestSettled},
1525			},
1526		}})
1527		if _, err := restoreAt(data, t0); err != nil {
1528			t.Fatalf("spent == MaxInt64 restore: %v", err)
1529		}
1530	
1531		// 上限 MaxInt64：单笔预估费用 MaxInt64 的现存预留占满额度。
1532		data = buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1533			id: "p-reserved-max", per: math.MaxInt64, total: math.MaxInt64,
1534			reqs: []quotaReqSpec{
1535				{id: "reserved", account: "u1", estFee: math.MaxInt64, state: RequestReserved},
1536			},
1537		}})
1538		if _, err := restoreAt(data, t0); err != nil {
1539			t.Fatalf("reserved == MaxInt64 restore: %v", err)
1540		}
1541	
1542		// 不同策略分别判断：同一出资账户的两条策略各自恰好占满 50，
1543		// 跨策略合计 100 不影响合法性。
1544		data = buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{
1545			{
1546				id: "p1", per: 100, total: 50,
1547				reqs: []quotaReqSpec{
1548					{id: "s1", account: "u1", estFee: 30, actualFee: 20, state: RequestSettled},
1549					{id: "r1", account: "u1", estFee: 30, state: RequestReserved},
1550				},
1551			},
1552			{
1553				id: "p2", per: 100, total: 50,
1554				reqs: []quotaReqSpec{
1555					{id: "s2", account: "u2", estFee: 30, actualFee: 20, state: RequestSettled},
1556					{id: "r2", account: "u2", estFee: 30, state: RequestReserved},
1557				},
1558			},
1559		})
1560		if _, err := restoreAt(data, t0); err != nil {
1561			t.Fatalf("two policies each at their own limit: %v", err)
1562		}
1563	}
1564	
1565	// TestRestoreCumulativeQuotaIgnoresNonOccupyingStates 验证只有现存预留与已
1566	// 结算实际费用占用累计额度：待审批、审批拒绝、待审批取消、待审批过期、已
1567	// 预留后取消、预留超时的请求都不占用；结算退回的差额也不计入已花费。
1568	func TestRestoreCumulativeQuotaIgnoresNonOccupyingStates(t *testing.T) {
1569		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
1570		// 累计上限仅 10：一笔实际费用 10 的已结算请求占满额度；其余请求费用均
1571		// 为 30（待审批系严格超过门槛 10），但都不占用额度，备份仍合法。
1572		data := buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1573			id: "p-free", per: 100, total: 10, threshold: 10,
1574			wait: 5 * time.Minute, reserveDur: time.Minute,
1575			reqs: []quotaReqSpec{
1576				{id: "settled", account: "u1", estFee: 10, actualFee: 10, state: RequestSettled},
1577				{id: "reserved-cancelled", account: "u1", estFee: 10, state: RequestCancelled, wasReserved: true},
1578				{id: "reservation-expired", account: "u1", estFee: 10, state: RequestReservationExpired},
1579				{id: "pending", account: "u1", estFee: 30, state: RequestPendingApproval},
1580				{id: "rejected", account: "u1", estFee: 30, state: RequestRejected, rejectReason: "no"},
1581				{id: "pending-expired", account: "u1", estFee: 30, state: RequestExpired},
1582				{id: "pending-cancelled", account: "u1", estFee: 30, state: RequestCancelled},
1583			},
1584		}})
1585		w2, err := restoreAt(data, t0)
1586		if err != nil {
1587			t.Fatalf("non-counting states restore: %v", err)
1588		}
1589		// 未到期的待审批请求不被改写；没有任何现存预留，账户预留余额为零。
1590		r, err := w2.Request("u1", "pending")
1591		if err != nil || r.State != RequestPendingApproval {
1592			t.Fatalf("pending request state = %v err = %v, want still pending", r.State, err)
1593		}
1594		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 0, Reserved: 0}) {
1595			t.Fatalf("payer balance = %+v, want zero reserved", bal)
1596		}
1597	}
1598	
1599	// ---- 并发 ----
1600	
1601	func TestExportConcurrentWithMutations(t *testing.T) {
1602		w, c := newTestWallet()
1603		t0 := c.t
1604		mustAccount(t, w, "payer", 1_000_000)
1605		mustAccount(t, w, "u1", 0)
1606		mustAccount(t, w, "u2", 0)
1607		if _, err := w.CreateSession("s1", "u1", "dev1", t0.Add(24*time.Hour)); err != nil {
1608			t.Fatal(err)
1609		}
1610		if _, err := w.CreateSession("s2", "u2", "dev2", t0.Add(24*time.Hour)); err != nil {
1611			t.Fatal(err)
1612		}
1613		if err := w.SavePolicy(PolicySpec{
1614			ID: "p1", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1", "u2"},
1615			Operation: "charge", Payee: "shop",
1616			StartsAt: t0.Add(-time.Hour), EndsAt: t0.Add(24 * time.Hour),
1617			MaxPerRequest: 100, MaxTotal: 1_000_000,
1618			MaxReserveDuration: time.Hour,
1619		}); err != nil {
1620			t.Fatal(err)
1621		}
1622	
1623		const n = 200
1624		var wg sync.WaitGroup
1625		var backups [][]byte
1626		var mu sync.Mutex
1627	
1628		// 申请/结算/取消/导出 并发；每个备份都必须是可恢复的完整状态。
1629		for g := 0; g < 4; g++ {
1630			g := g
1631			wg.Add(1)
1632			go func() {
1633				defer wg.Done()
1634				for i := 0; i < n; i++ {
1635					rid := fmt.Sprintf("g%d-r%d", g, i)
1636					in := RequestInput{
1637						PolicyID: "p1", RequestID: rid, AccountID: "u2", SessionID: "s2",
1638						DeviceID: "dev2", Operation: "charge", Payee: "shop", EstimatedFee: 1,
1639					}
1640					if _, err := w.Apply(in); err != nil {
1641						t.Errorf("apply: %v", err)
1642						return
1643					}
1644					switch i % 3 {
1645					case 0:
1646						if _, err := w.Settle("u2", rid, 1); err != nil {
1647							t.Errorf("settle: %v", err)
1648						}
1649					case 1:
1650						if _, err := w.Cancel("u2", rid); err != nil {
1651							t.Errorf("cancel: %v", err)
1652						}
1653					}
1654				}
1655			}()
1656		}
1657		wg.Add(1)
1658		go func() {
1659			defer wg.Done()
1660			for i := 0; i < n; i++ {
1661				data, err := w.Export()
1662				if err != nil {
1663					t.Errorf("export: %v", err)
1664					return
1665				}
1666				mu.Lock()
1667				backups = append(backups, data)
1668				mu.Unlock()
1669			}
1670		}()
1671		wg.Wait()
1672	
1673		if len(backups) == 0 {
1674			t.Fatal("no backups captured")
1675		}
1676		for i, data := range backups {
1677			w2, err := Restore(data)
1678			if err != nil {
1679				t.Fatalf("backup %d not restorable: %v", i, err)
1680			}
1681			// 恢复出的钱包余额自洽：非负且预留不凭空消失。
1682			for _, id := range []string{"payer"} {
1683				bal, err := w2.Balance(id)
1684				if err != nil {
1685					t.Fatalf("backup %d balance: %v", i, err)
1686				}
1687				if bal.Available < 0 || bal.Reserved < 0 {
1688					t.Fatalf("backup %d negative balance: %+v", i, bal)
1689				}
1690			}
1691		}
1692	
1693		// 最终状态本身也必须可导出/恢复且账本完整（用与源钱包相同的受控时刻，
1694		// 避免恢复时钟把未到期预留结算掉而混淆比较）。
1695		final, err := w.Export()
1696		if err != nil {
1697			t.Fatal(err)
1698		}
1699		w2, err := restoreAt(final, c.t)
1700		if err != nil {
1701			t.Fatal(err)
1702		}
1703		if l1, l2 := len(w.Ledger()), len(w2.Ledger()); l1 != l2 {
1704			t.Fatalf("final ledger length = %d, want %d", l2, l1)
1705		}
1706	}
